SELECT
etrf.item_id as item_id,
etrf.status as status
FROM bt_expt_turn_result_filter etrf

  INNER JOIN bt_dataset_item_snapshot dis ON etrf.eval_set_version_id = dis.version_id AND etrf.item_id = dis.item_id

WHERE 1=1

  AND etrf.space_id = #{cond.spaceId}


  AND etrf.expt_id = #{cond.exptId}





        AND etrf.item_id IN

          #{value}



        AND etrf.item_id = #{filter.values[0]}


        AND etrf.item_id BETWEEN #{filter.values[0]} AND #{filter.values[1]}


        AND etrf.item_id != #{filter.values[0]}


        AND etrf.item_id NOT IN

          #{value}









        AND etrf.status IN

          #{value}



        AND etrf.status = #{filter.values[0]}


        AND etrf.status BETWEEN #{filter.values[0]} AND #{filter.values[1]}


        AND etrf.status != #{filter.values[0]}


        AND etrf.status NOT IN

          #{value}






  AND etrf.created_date = #{cond.createdDate}


  AND etrf.eval_set_version_id = #{cond.evalSetVersionId}


  AND etrf.evaluator_score_corrected ${cond.evaluatorScoreCorrected.op} #{cond.evaluatorScoreCorrected.values[0]}


  AND dis.sync_ck_date = #{cond.evalSetSyncCkDate}






          AND JSON_EXTRACT(etrf.eval_target_data, CONCAT('$.', #{filter.key})) = #{filter.values[0]}


          AND JSON_EXTRACT(etrf.eval_target_data, CONCAT('$.', #{filter.key})) LIKE CONCAT('%', #{filter.values[0]}, '%')


          AND JSON_EXTRACT(etrf.eval_target_data, CONCAT('$.', #{filter.key})) NOT LIKE CONCAT('%', #{filter.values[0]}, '%')


          AND JSON_EXTRACT(etrf.eval_target_data, CONCAT('$.', #{filter.key})) != #{filter.values[0]}








          AND ABS(JSON_EXTRACT(etrf.evaluator_score, CONCAT('$.', #{filter.key})) - #{filter.values[0]}) < 1e-8


          AND JSON_EXTRACT(etrf.evaluator_score, CONCAT('$.', #{filter.key})) ${filter.op} #{filter.values[0]}


          AND JSON_EXTRACT(etrf.evaluator_score, CONCAT('$.', #{filter.key})) BETWEEN #{filter.values[0]} AND #{filter.values[1]}






  AND (
  etrf.item_id = #{cond.keywordSearch.keyword}


      OR JSON_EXTRACT(etrf.eval_target_data, CONCAT('$.', #{filter.key})) LIKE CONCAT('%', #{cond.keywordSearch.keyword}, '%')


  )

ORDER BY etrf.item_idx



    #{cond.page.limit}


    OFFSET #{cond.page.offset}

